  "settings.audio": "独立音频通道", "settings.display": "显示与辅助功能", "settings.music": "背景音乐", "settings.track": "循环曲目", "settings.musicVolume": "音乐音量", "settings.sfx": "动作音效", "settings.sfxVolume": "音效音量", "settings.ambience": "风声与极地环境声", "settings.ambienceVolume": "环境声音量",
