export const dictionaries = { fa, en, zh };
export function translate(language: Language, key: string, vars?: Record<string, string | number>): string {
  let text = dictionaries[language][key] ?? en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) text = text.replaceAll(`{${k}}`, String(v));
  return text;
}
export function locale(language: Language): string { return language === "fa" ? "fa-IR" : language === "zh" ? "zh-CN" : "en-US"; }
export type TranslationKey = keyof typeof en;
